// Mapear valores do formulário para labels legíveis
const d = $input.first().json.body;

const objetivoMap = {
  'bemestar':       'Pernas pesadas e inchaço diário',
  'retencao':       'Retenção que nada resolve',
  'estetica':       'Celulite e medidas',
  'localizada':     'Zona específica — sessão localizada',
  'pos-parto':      'Pós-parto — voltar ao normal',
  'pos-operatorio': 'Pós-operatório — recuperar mais rápido',
  'gravidez':       'Gravidez — inchaço e desconforto',
  'duvida':         'Ainda não sei bem — a explorar'
};

const zonaMap = {
  'corpo-inteiro':   'Corpo inteiro',
  'abdomen':         'Abdómen',
  'abdomen-pernas':  'Abdómen + Pernas',
  'rosto':           'Rosto',
  'avaliacao':       'Prefiro que me avaliem'
};

const urgenciaMap = {
  'esta-semana':  'Esta semana',
  'duas-semanas': 'Próximas 2 semanas',
  'este-mes':     'Este mês',
  'explorar':     'Ainda a explorar'
};

const experienciaMap = {
  'primeira-vez':   'Primeira vez',
  'sem-resultado':  'Já fez mas sem resultado',
  'positiva':       'Já fez e adorou'
};

function normalizeTel(tel) {
  const digits = (tel || '').replace(/\D/g, '');
  if (digits.startsWith('351') && digits.length === 12) return digits;
  if (digits.startsWith('9') && digits.length === 9) return '351' + digits;
  if (digits.startsWith('351')) return digits;
  return digits;
}

const dataRaw = d.data || new Date().toISOString();
const dataPt = new Date(dataRaw).toLocaleString('pt-PT', {
  weekday: 'long', day: 'numeric', month: 'long',
  year: 'numeric', hour: '2-digit', minute: '2-digit',
  timeZone: 'Europe/Lisbon'
});

return {
  nome:               d.nome || '',
  email:              d.email || '',
  telefone:           d.telefone || '',
  telefone_norm:      normalizeTel(d.telefone),
  objetivo:           d.objetivo || '',
  objetivo_label:     objetivoMap[d.objetivo]     || d.objetivo     || 'Não especificado',
  zona:               d.zona || '',
  zona_label:         zonaMap[d.zona]             || d.zona         || 'Não especificado',
  urgencia:           d.urgencia || '',
  urgencia_label:     urgenciaMap[d.urgencia]     || d.urgencia     || 'Não especificado',
  experiencia:        d.experiencia || '',
  experiencia_label:  experienciaMap[d.experiencia] || d.experiencia || 'Não especificado',
  pagina:             d.pagina || 'drenagem-linfatica',
  data_iso:           dataRaw,
  data_pt:            dataPt,
  utm_source:         d.utm_source   || '',
  utm_medium:         d.utm_medium   || '',
  utm_campaign:       d.utm_campaign || ''
};
